{"code":"class Solution:
    def uniquePaths(self, m: int, n: int) -> int:
        # Create a 2D grid of size m x n
        grid = [[0] * n for _ in range(m)]

        # Initialize the first row and first column with 1
        for i in range(m):
            grid[i][0] = 1
        for j in range(n):
            grid[0][j] = 1

        # Calculate the number of unique paths for each cell
        for i in range(1, m):
            for j in range(1, n):
                grid[i][j] = grid[i-1][j] + grid[i][j-1]

        # Return the number of unique paths to reach the finish
        return grid[m-1][n-1]"}

